function bindExport(){const preview=$("exportPreview"),refresh=$("btnRefreshExport"),button=$("btnExportCampaign");if(!preview||!refresh||!button)return;const sync=()=>{preview.value=JSON.stringify(mockCampaignPayload(),null,2)};refresh.onclick=sync;button.onclick=window.__tasRunMockExport}
window.__tasRunMockExport=async button=>{button.disabled=true;setStatus("mock側へ出力中…");try{if(isLocalFile())throw new Error("ローカルファイルでは出力できません。node server.cjs で起動してください");const payload=mockCampaignPayload();const res=await fetch("/api/export-campaign",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok||data.error)throw new Error(data.error?.message||res.status);setStatus(`mock側へ出力しました: ${data.saved.join(", ")}`)}catch(e){setStatus(`出力失敗: ${e.message}`)}finally{button.disabled=false}};
/* 画像はmock2のimagesフォルダへ集約し、下書きにはパス(/images/名前)だけ保持する。
   file://で開いた場合のみ従来のdata URL埋め込みへフォールバック */
function handleImageInput(file,assign,doneMessage){if(!file)return;const done=url=>{assign(url);saveWorkspaceDraft(true);renderTab();setStatus(doneMessage||"画像を保存しました")};if(isLocalFile()){const r=new FileReader();r.onload=()=>done(r.result);r.readAsDataURL(file);return}const reader=new FileReader();reader.onload=async()=>{try{const res=await fetch("/api/upload-image",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({filename:file.name,dataUrl:reader.result})});const d=await res.json();if(!res.ok||d.error)throw new Error(d.error?.message||res.status);done(d.url)}catch(e){assign(reader.result);saveWorkspaceDraft(true);renderTab();setStatus("画像を一時保存しました（サーバー保存は未接続）")}};reader.readAsDataURL(file)}
async function callLLM(system,messages,max_tokens){if(isLocalFile())throw new Error("ローカルモードではAI APIを既定で使用しません");const res=await fetch("/api/llm",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({system,messages,max_tokens})});const d=await res.json();if(!res.ok||d.error)throw new Error(d.error?.message||res.status);setStatus(`完了 (in:${d.usage?.input_tokens||0} / out:${d.usage?.output_tokens||0})`);return d.text}
function sceneGenerationPrompt(instruction){const s=withSceneOverride(scene());const targets=sceneTargets().map(n=>`- ${sceneRef(n)} = ${sceneRefLabel(n)}`).join("\n");return `対象シーンの構造化データの叩き台を作ってください。出力はJSONオブジェクト1個のみ。説明文・コードフェンスは不要です。

# キャンペーン
名前: ${campaignName}
世界・ジャンル: ${campaignWorld}
テーマ: ${campaignTheme}
用語・禁止事項: ${campaignTerms}

# 対象シーンの現在データ（既存の要素は削らず、指示に沿って改良・追加する）
${JSON.stringify(s,null,2)}

# 出力スキーマ（このキーのみ使う）
{
 "name": "シーン名",
 "brief": "開始時の説明",
 "goal": "このシーンの目的",
 "discoveries": [{"label":"要素名","category":"main|place|image|sense|object|foreshadow|npc","importance":"major|support|flavor","surface":"プレイヤーが見聞きする情報","trigger":"開示方法","fact":"ゲームが保持する確定事実","tags":["発見済み名"],"aliases":["プレイヤー入力の照合語。短い別名"],"dc":"0|8|12|15|18（調べる判定の難易度。0は判定なしで即開示）"}],
 "transitions": [{"trigger":"プレイヤーの行動","requires":"必要な発見済み名（AND / OR 可。不要なら空文字）","target":"下記のシーン参照のいずれか"}],
 "dialogueRules": [{"speaker":"gm|member|npc|system","condition":"発火条件（flag:発見済み名 / discovery:項目キー。常時なら空文字）","priority":"high|medium|low","line":"発言内容","eventType":"空文字|flag_add|item_grant|npc_join|scene_unlock|battle_start|discovery_reveal","targetId":"イベント対象","eventNotes":"補足","once":true,"hiddenUntilTriggered":false}],
 "gmSceneNotes": "GM向け補足メモ"
}

# transitionsのtargetに使えるシーン参照
${targets}

# 指示
${instruction}

未確定の設定を勝手に断定しない。確定できない事項はgmSceneNotesに【要議論】として書く。`}
function parseGeneratedScene(text){const raw=String(text||"");const start=raw.indexOf("{");const end=raw.lastIndexOf("}");if(start<0||end<=start)throw new Error("JSONが見つかりません");return JSON.parse(raw.slice(start,end+1))}
function applyGeneratedScene(data){const key=sceneKey();const o={...(sceneOverrides[key]||{})};if(typeof data.name==="string"&&data.name)o.name=data.name;if(typeof data.brief==="string"&&data.brief)o.brief=data.brief;if(typeof data.goal==="string"&&data.goal)o.goal=data.goal;if(Array.isArray(data.discoveries))o.discoveries=data.discoveries.map((d,i)=>normalizeDiscoveryFor(scene(),d,i));if(Array.isArray(data.transitions))o.transitions=data.transitions.map(t=>({trigger:String(t.trigger||""),requires:String(t.requires||""),conditionValue:String(t.requires||""),target:String(t.target||"")})).filter(t=>t.trigger||t.requires||t.target);if(Array.isArray(data.dialogueRules))o.dialogueRules=data.dialogueRules.map(normalizeDialogueRule);if(typeof data.gmSceneNotes==="string"&&data.gmSceneNotes)o.gmSceneNotes=data.gmSceneNotes;sceneOverrides[key]=o;saveWorkspaceDraft(true)}
function bindDraft(){document.querySelectorAll("[data-instruction-template]").forEach(btn=>btn.onclick=()=>{const t=INSTRUCTION_TEMPLATES[Number(btn.dataset.instructionTemplate)];const box=$("instruction");box.value=box.value.trim()?`${box.value.trim()}\n${t.text}`:t.text;box.focus();setStatus("テンプレートを挿入しました。【】を書き換えてください")});
$("btnWish").onclick=async()=>{const wish=$("wishInput").value.trim();if(!wish){alert("やりたいことを一言で書いてください");return}setStatus("指示文を作成中…");try{const text=await callLLM("あなたはTRPG制作ツールの入力支援です。ユーザーの要望を、シーン生成AIへの具体的な指示文（3〜5行の箇条書き）に清書してください。対象シーンの現状を踏まえ、主線・伏線・禁止事項の観点を含めます。出力は指示文のみ。",[{role:"user",content:`対象シーンの現状:\n${JSON.stringify(withSceneOverride(scene()),null,2)}\n\n要望: ${wish}`}],1000);$("instruction").value=text.trim();setStatus("指示文を作成しました。確認して「叩き台を生成」を押してください")}catch(e){setStatus("指示文の作成に失敗しました: "+e.message)}};
$("btnGenerate").onclick=async()=>{const inst=$("instruction").value.trim();if(!inst){alert("指示を入力してください");return}setStatus("生成中…");try{const text=await callLLM("あなたはTRPGの共同制作者です。出力は指定スキーマのJSONオブジェクト1個のみ。前置き・説明・コードフェンスを付けない。",[{role:"user",content:sceneGenerationPrompt(inst)}],8000);const parsed=parseGeneratedScene(text);draft=JSON.stringify(parsed,null,2);renderTab();setStatus("生成完了。内容を確認してシーンへ取り込んでください")}catch(e){setStatus("エラー: "+e.message)}};$("btnReview").onclick=async()=>{setStatus("レビュー中…");try{review=await callLLM("TRPGシナリオの品質レビュアーです。シーンの構造化データ案を検査し、矛盾・未定義の参照（存在しない発見済み名やシーン参照）・秘密の早期開示・演出上の弱点を重大度順に指摘してください。",[{role:"user",content:`キャンペーン設定:\n${campaignWorld}\nテーマ: ${campaignTheme}\n\n現在のシーン:\n${JSON.stringify(withSceneOverride(scene()),null,2)}\n\n生成案:\n${$("draft").value}`}],4000);renderTab();setStatus("レビュー完了")}catch(e){setStatus("エラー: "+e.message)}};$("btnApprove").onclick=()=>{try{const data=parseGeneratedScene($("draft").value);applyGeneratedScene(data);activeTab="structure";renderScenes();renderAll();setStatus("シーンへ取り込みました。各タブで内容を確認してください")}catch(e){setStatus("取り込み失敗: "+e.message)}}}
async function init(){loadWorkspaceDraft();if(isLocalFile()){context={backend:"local",files:{},dataFiles:{}};setStatus("ローカルモード: AI APIは既定で使用しません")}else{try{const r=await fetch("/api/context");context=await r.json();if(context.error)throw new Error(context.error.message);setStatus(`接続済み: ${context.backend}`)}catch(e){context={backend:"local",files:{},dataFiles:{}};setStatus("ローカルモードに切り替えました")}}
  /* 章構造(structureChapters)は一度作ると再利用される。/api/context の到着前に作られると
     fallbackScenes(index.html内の見本5シーン)で固定され、実データに戻らなくなる。
     contextが揃ったこの時点で、下書きの構造を復元するか、無ければ作り直す */
  try{const raw=localStorage.getItem(DRAFT_KEY);const parsed=raw?JSON.parse(raw):null;const saved=parsed?(parsed.data||parsed):null;
    if(saved&&Array.isArray(saved.chapterOrder)&&saved.chapterOrder.length)chapterOrder=saved.chapterOrder;
  }catch(e){}
  /* 下書きに残った構造は使わない。旧IDや作りかけの出口を抱えていることがあり、
     実データ(context)より古い。シーンごとの編集内容はsceneOverridesに別途あるので、
     ここで作り直しても作者の入力は失われない */
  structureChapters=null;
  renderScenes();renderAll()}
$("layerTabs").onclick=e=>{const b=e.target.closest("[data-tab]");if(!b)return;activeTab=b.dataset.tab;renderScenes();renderAll()};$("btnBuild").onclick=()=>{activeTab="export";renderScenes();renderAll();setStatus("出力内容を確認してください")};$("btnSaveDraft").onclick=()=>saveCampaignFile();$("btnLoadCampaign").onclick=()=>$("campaignFileInput").click();$("campaignFileInput").onchange=e=>loadCampaignFile(e.target.files?.[0]);$("toggleRightSwitch").onchange=e=>{rightPanelEnabled=e.target.checked;syncRightPanel();saveWorkspaceDraft()};if($("btnNewScene"))$("btnNewScene").onclick=()=>setStatus("新規シーン作成は次段階で接続します");init();
